// TokenMintRequestToEnvVar converts TokenMintRequest to environment variable key-value pairs.
func TokenMintRequestToEnvVar(v *TokenMintRequest) map[string]string {
	if v == nil {
		return nil
	}
	result := make(map[string]string)
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_INPUT_TOKEN"] = v.InputToken
	if v.CloudProof != nil {
		for k, val := range cloudidentity.CloudIdentityProofToEnvVar(v.CloudProof) {
			result[k] = val
		}
	}
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_CONTINUITY_TOKEN"] = v.ContinuityToken
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_AUD"] = v.Aud
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_EXP"] = strconv.FormatInt(v.Exp, 10)
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_TOKEN_PURPOSE"] = token.TokenPurposeToString(v.TokenPurpose)
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_SUBJECT"] = v.Subject
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_OFFLINE_ACCESS"] = strconv.FormatBool(v.OfflineAccess)
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_LOCALITY_TOKEN"] = v.LocalityToken
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_PROJECT"] = v.Project
	if len(v.ServiceAuds) > 0 {
		result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_SERVICE_AUDS"] = strings.Join(v.ServiceAuds, ",")
	}
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_TRACE_ID"] = v.TraceId
	result["PROTO_COMMON_TOKENREQUEST_TOKEN_MINT_REQUEST_NOOP"] = strconv.FormatBool(v.Noop)
	return result
}

